// Gerado por scripts/gerar-profissoes.py a partir das configurações do
// RPGJobs no servidor. Não edite à mão: rode o script de novo.

export type JobId =
  | "blacksmith"
  | "armorer"
  | "jeweler"
  | "alchemist"
  | "culinarian"
  | "miner"
  | "woodcutter"
  | "fisher"
  | "gatherer";

export type Job = { id: JobId; name: string; station?: { x: number; z: number } };

// [endereço do material, quantidade]
export type MaterialAmount = [string, number];

export type JobMaterial = {
  id: string;
  slug: string;
  name: string;
  icon?: string;
  source: "coleta" | "monstro";
  // coleta: o ponto que dá o material; monstro: a família que derruba
  job?: JobId;
  spot?: string;
  region?: string;
  special?: boolean;
  amount?: string;
  family?: string;
  level: number;
  levels: string;
  // itens que usam o material e ferramentas que pedem ele
  usedBy: string[];
  tools: string[];
};

export type JobItem = {
  slug: string;
  name: string;
  job: JobId;
  type: "weapon" | "armor" | "necklace" | "earring" | "ring" | "potion" | "food";
  kind: string;
  category: string;
  level: number;
  // itens feitos de uma vez
  amount: number;
  materials: MaterialAmount[];
  stat: string;
  // bônus da raridade Mítica, a mais alta
  bonus: string[];
  icon?: string;
};

export type RecipeCategory = {
  job: JobId;
  name: string;
  level: number;
  resistance?: string;
  items: string[];
};

export type Spot = {
  job: JobId;
  level: number;
  levels: string;
  region: string;
  name: string;
  main: string;
  special: string;
};

export type Tool = { job: JobId; name: string; level: number; money: number; materials: MaterialAmount[] };

